mapper.select:
SELECT e.equipment_id, e.equipment_name, c.category_name AS category, e.status, e.qr_image_path, e.created_at FROM EQUIPMENT e JOIN CATEGORY c ON e.category_id = c.category_id
AND c.category_name = #{category}
ORDER BY e.equipment_id ASC LIMIT #{pageSize} OFFSET #{offset}

mapper.update:
UPDATE CATEGORY
SET category_name = #{categoryName}
WHERE category_id = #{categoryId}
